@MappedMethod public void playSoundAtBlockCenter(BlockPos pos,SoundEvent sound,SoundCategory category,int volume,int pitch,boolean useDistance){playSoundAtBlockCenter(pos,sound,category,(float)volume,(float)pitch,useDistance);}

